import { test, expect } from '@playwright/test';

test.describe('Modal Dialog Focus Management', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should focus back on trigger button after modal closes', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: /open modal/i });
    await triggerButton.click();

    const modalCloseButton = page.getByRole('button', { name: /close modal/i });
    await modalCloseButton.click();

    await expect(triggerButton).toBeFocused();
  });

  test('should keep focus on trigger button when modal is closed with escape key', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: /open modal/i });
    await triggerButton.click();

    await page.keyboard.press('Escape');

    await expect(triggerButton).toBeFocused();
  });
});
